@router.patch(\"/agents/{agent_id}/status\")
def set_agent_status(agent_id: uuid.UUID, payload: AgentStatusBody, request: Request,
                     user: User = Depends(policy_admin), db: Session = Depends(get_db)) -> dict:
    """Suspend, reactivate, or deactivate an agent account."""
    agent = db.scalar(select(User).where(User.id == agent_id, User.role == \"agent\").with_for_update())
    if not agent:
        raise HTTPException(status_code=404, detail=\"Agent not found\")
    _require_branch(user, agent.branch_id or agent.id)  # branch_id may be None for rare edge case
    if agent.id == user.id:
        raise HTTPException(status_code=403, detail=\"You cannot change your own account status\")
    if agent.status == payload.status:
        return {\"id\": str(agent.id), \"status\": agent.status}
    before = agent.status
    agent.status = payload.status
    audit(db, actor_id=user.id, action=f\"agent.status_changed\", entity_type=\"user\", entity_id=agent.id,
          before={\"status\": before}, after={\"status\": agent.status}, reason=payload.reason,
          request_id=request.headers.get(\"x-request-id\"))
    db.commit()
    return {\"id\": str(agent.id), \"full_name\": agent.full_name, \"status\": agent.status}


